float vrchStitchLine(vec2 point, vec2 direction, float width, float length) {
  vec2 normal = vec2(-direction.y, direction.x);
  float across = abs(dot(point, normal));
  float along = abs(dot(point, direction));
  float antialias = max(fwidth(across) * 1.5, 0.008);
  float widthMask = 1.0 - smoothstep(width - antialias, width + antialias, across);
  float endMask = 1.0 - smoothstep(length - 0.08, length, along);
  return widthMask * endMask;
}
float vrchThreadHash(vec2 point) {
  return fract(sin(dot(point, vec2(53.19, 17.71))) * 43758.5453);
}
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  vec2 aspect = vec2(iResolution.x / iResolution.y, 1.0);
  vec2 grid = uv * aspect * uParam_density;
  vec2 cell = floor(grid);
  vec2 local = fract(grid) - 0.5;
  vec2 sampleUv = (cell + 0.5) / (aspect * uParam_density);
  vec4 image = vrchSampleSource0(sampleUv);
  float response = clamp((uParam_contrast - 1.16) / 0.34, 0.0, 1.0);
  float stitchWidth = 0.055 + response * 0.145;
  float stitchLength = 0.35 + response * 0.13;
  float angle = uParam_direction * 6.28318530718 + (vrchThreadHash(cell) - 0.5) * uParam_roughness;
  vec2 directionA = vec2(cos(angle), sin(angle));
  vec2 directionB = vec2(-directionA.y, directionA.x);
  float stitchA = vrchStitchLine(local, directionA, stitchWidth, stitchLength);
  float stitchB = vrchStitchLine(local, directionB, stitchWidth, stitchLength);
  float stitch = max(stitchA, stitchB * 0.82);
  float ridge = clamp(0.5 + dot(local, directionA) * 1.8, 0.0, 1.0);
  vec3 threadBase = max(image.rgb, vec3(0.0));
  float ridgeLight = mix(0.72, 1.0 + uParam_contrast * 0.3 + response * 0.55, ridge);
  vec3 threadColor = threadBase * ridgeLight;
  threadColor += threadBase * stitchA * response * 0.45;
  vec3 textile = mix(uParam_fabric.rgb, threadColor, stitch);
  fragColor = vec4(mix(image.rgb, textile, uParam_amount), image.a);
}
